def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]

    opp_d = opp.count('D')
    my_d = my.count('D')

    # Early cooperation to establish mutual CC
    if n < 4:
        return 'C'

    # Punish sustained defection, but probe rarely to escape DD lock
    if opp_d >= n - 2 and n >= 6:
        if n % 19 == 0:
            return 'C'
        return 'D'

    last_opp = opp[-1]

    # Endgame: exploit cooperative opponents, avoid being sucker
    remaining = 100 - n
    if remaining <= 2:
        if opp_d == 0:
            return 'D'
        if last_opp == 'D':
            return 'D'
        if remaining == 1:
            return 'D'
        return 'C'

    # Forgiveness / retaliate based on last opponent move
    if last_opp == 'C':
        # Mostly cooperate; only rare probing against very cooperative opponents
        if n >= 10 and opp_d <= n // 10:
            if n % 13 == 0:
                return 'D'
        # If we defected recently, return to cooperation to repair
        if my[-1] == 'D':
            return 'C'
        return 'C'

    # Opponent defected last round
    # Retaliate, but forgive quickly if opponent is mostly cooperative
    if opp_d * 3 <= n and n >= 5:
        # Forgiving retaliation: defect once, then cooperate next if they do
        if n >= 2 and opp[-2] == 'D' and opp_d * 2 <= n:
            return 'C'
        if rng.random() < 0.4:
            return 'C'
        return 'D'

    # Opponent has significant defection rate
    if n >= 2 and opp[-2] == 'D' and opp_d >= 3:
        # Two defections in a row -> persistent retaliation, occasional probe
        if n % 11 == 0:
            return 'C'
        return 'D'

    # Default retaliation with forgiveness chance
    if rng.random() < 0.25:
        return 'C'
    return 'D'
